import{_ as e,o as r,c as a,ag as i}from"./chunks/framework.BZohXCq9.js";const m=JSON.parse('{"title":"Tractors","description":"","frontmatter":{},"headers":[],"relativePath":"wiggles.md","filePath":"wiggles.md"}'),d={name:"wiggles.md"};function l(o,t,s,n,g,h){return r(),a("div",null,[...t[0]||(t[0]=[i('<h1 id="tractors" tabindex="-1">Tractors <a class="header-anchor" href="#tractors" aria-label="Permalink to &quot;Tractors&quot;">​</a></h1><p>Tractors are one of the main types of vehicles in <strong>Farming And Friends</strong>. They are primarily used for agricultural work, including plowing, cultivating and planting fields.</p><p>Tractors are available across multiple levels, with higher-level tractors generally offering improved road and field speeds. Some tractors are also obtained through events, promotions, starter packs, Companies or other limited-time methods.</p><h2 id="tractor-information" tabindex="-1">Tractor Information <a class="header-anchor" href="#tractor-information" aria-label="Permalink to &quot;Tractor Information&quot;">​</a></h2><p>Each tractor has two listed speed values:</p><table tabindex="0"><thead><tr><th>Statistic</th><th>Description</th></tr></thead><tbody><tr><td><strong>Road Speed</strong></td><td>The tractor&#39;s maximum speed when travelling on roads and other non-field surfaces.</td></tr><tr><td><strong>Field Speed</strong></td><td>The tractor&#39;s maximum speed while operating on a field.</td></tr></tbody></table><p>Speed values are displayed out of <strong>100</strong>, with higher values representing faster vehicles.</p><blockquote><p><strong>Note:</strong> Actual vehicle performance may vary depending on terrain, equipment being towed and other gameplay conditions.</p></blockquote><hr><h2 id="level-1" tabindex="-1">Level 1 <a class="header-anchor" href="#level-1" aria-label="Permalink to &quot;Level 1&quot;">​</a></h2><p>Level 1 tractors are the starting tier of tractors and are designed primarily for early-game farming.</p><table tabindex="0"><thead><tr><th>Name</th><th>Accessibility</th><th style="text-align:right;">Road Speed</th><th style="text-align:right;">Field Speed</th></tr></thead><tbody><tr><td>🚜 <strong>ZM80</strong></td><td>1,500 Coins from FarmCo</td><td style="text-align:right;">41/100</td><td style="text-align:right;">33/100</td></tr><tr><td>🚜 <strong>Rusty ZM80</strong></td><td>33% chance to be given when starting the game</td><td style="text-align:right;">32/100</td><td style="text-align:right;">24/100</td></tr></tbody></table><h3 id="zm80" tabindex="-1">ZM80 <a class="header-anchor" href="#zm80" aria-label="Permalink to &quot;ZM80&quot;">​</a></h3><p>The ZM80 is a Level 1 tractor available from FarmCo for <strong>1,500 Coins</strong>.</p><h3 id="rusty-zm80" tabindex="-1">Rusty ZM80 <a class="header-anchor" href="#rusty-zm80" aria-label="Permalink to &quot;Rusty ZM80&quot;">​</a></h3><p>The Rusty ZM80 is a starter variant of the ZM80. New players have a <strong>33% chance</strong> of receiving it when starting the game.</p><hr><h2 id="level-2" tabindex="-1">Level 2 <a class="header-anchor" href="#level-2" aria-label="Permalink to &quot;Level 2&quot;">​</a></h2><p>Level 2 tractors provide improved performance over the starting tractors and are available for players progressing through the early game.</p><table tabindex="0"><thead><tr><th>Name</th><th>Accessibility</th><th style="text-align:right;">Road Speed</th><th style="text-align:right;">Field Speed</th></tr></thead><tbody><tr><td>🚜 <strong>H488</strong></td><td>4,500 Coins from FarmCo</td><td style="text-align:right;">46/100</td><td style="text-align:right;">37/100</td></tr><tr><td>🚜 <strong>IMT650</strong></td><td>5,500 Coins from FarmCo</td><td style="text-align:right;">49/100</td><td style="text-align:right;">40/100</td></tr><tr><td>🚜 <strong>Rusty Tractor</strong></td><td>90 Robux from FarmCo</td><td style="text-align:right;">46/100</td><td style="text-align:right;">37/100</td></tr></tbody></table><hr><h2 id="level-3" tabindex="-1">Level 3 <a class="header-anchor" href="#level-3" aria-label="Permalink to &quot;Level 3&quot;">​</a></h2><p>Level 3 includes several specialised and higher-performance vehicles. Some vehicles in this level are obtained through limited-time promotions or special packs.</p><table tabindex="0"><thead><tr><th>Name</th><th>Accessibility</th><th style="text-align:right;">Road Speed</th><th style="text-align:right;">Field Speed</th></tr></thead><tbody><tr><td>🚜 <strong>GD428</strong></td><td>35,000 Coins from FarmCo</td><td style="text-align:right;">38/100</td><td style="text-align:right;">31/100</td></tr><tr><td>🚜 <strong>Moped</strong></td><td>72,000 Coins from FarmCo</td><td style="text-align:right;">43/100</td><td style="text-align:right;">35/100</td></tr><tr><td>🚜 <strong>Fordson</strong></td><td>265 Robux from FarmCo</td><td style="text-align:right;">37/100</td><td style="text-align:right;">30/100</td></tr><tr><td>🚜 <strong>Foxx Chamber 105</strong></td><td>Starter Pack</td><td style="text-align:right;">49/100</td><td style="text-align:right;">40/100</td></tr><tr><td>🚜 <strong>SOPT</strong></td><td>Walmart Promotion — unavailable</td><td style="text-align:right;">51/100</td><td style="text-align:right;">31/100</td></tr><tr><td>🚜 <strong>Super ZM80</strong></td><td>Mod Exclusive</td><td style="text-align:right;">99/100</td><td style="text-align:right;">99/100</td></tr></tbody></table><blockquote><p><strong>Note:</strong> Some Level 3 vehicles are not normally obtainable. Availability can change if an event, promotion or special offer returns.</p></blockquote><hr><h2 id="level-4" tabindex="-1">Level 4 <a class="header-anchor" href="#level-4" aria-label="Permalink to &quot;Level 4&quot;">​</a></h2><p>Level 4 tractors are intended for more advanced farming and forestry operations.</p><table tabindex="0"><thead><tr><th>Name</th><th>Accessibility</th><th style="text-align:right;">Road Speed</th><th style="text-align:right;">Field Speed</th></tr></thead><tbody><tr><td>🚜 <strong>GD216</strong></td><td>120,000 Coins from FarmCo</td><td style="text-align:right;">33/100</td><td style="text-align:right;">27/100</td></tr><tr><td>🚜 <strong>AP450</strong></td><td>150,000 Coins from FarmCo</td><td style="text-align:right;">48/100</td><td style="text-align:right;">39/100</td></tr><tr><td>🪵 <strong>LHT340</strong></td><td>85,000 Coins from FarmCo</td><td style="text-align:right;">37/100</td><td style="text-align:right;">30/100</td></tr><tr><td>🪵 <strong>Industrial Log Hauler</strong></td><td>315,000 Coins from FarmCo</td><td style="text-align:right;">37/100</td><td style="text-align:right;">30/100</td></tr><tr><td>🚜 <strong>ER80T</strong></td><td>265 Robux from FarmCo</td><td style="text-align:right;">37/100</td><td style="text-align:right;">30/100</td></tr></tbody></table><p>The LHT340 and Industrial Log Hauler are particularly associated with forestry and transporting logs.</p><hr><h2 id="level-5" tabindex="-1">Level 5 <a class="header-anchor" href="#level-5" aria-label="Permalink to &quot;Level 5&quot;">​</a></h2><p>Level 5 contains some of the highest-tier tractors and a number of limited or event-exclusive vehicles.</p><table tabindex="0"><thead><tr><th>Name</th><th>Accessibility</th><th style="text-align:right;">Road Speed</th><th style="text-align:right;">Field Speed</th></tr></thead><tbody><tr><td>🚜 <strong>Challenger MT9</strong></td><td>600,000 Coins from FarmCo</td><td style="text-align:right;">44/100</td><td style="text-align:right;">36/100</td></tr><tr><td>🚜 <strong>Claas Xerion 5000</strong></td><td>285 Robux from FarmCo</td><td style="text-align:right;">48/100</td><td style="text-align:right;">39/100</td></tr><tr><td>🚜 <strong>Foxx Metal Tech X1</strong></td><td>315 Robux from FarmCo</td><td style="text-align:right;">51/100</td><td style="text-align:right;">41/100</td></tr><tr><td>🚜 <strong>KM472</strong></td><td>Christmas Vehicle Pack</td><td style="text-align:right;">49/100</td><td style="text-align:right;">40/100</td></tr><tr><td>🚜 <strong>Zalter 500</strong></td><td>Zaltar Pack</td><td style="text-align:right;">51/100</td><td style="text-align:right;">40/100</td></tr><tr><td>🚜 <strong>Sleigh</strong></td><td>2021 Christmas Event</td><td style="text-align:right;">63/100</td><td style="text-align:right;">51/100</td></tr><tr><td>🚜 <strong>Vertra 135</strong></td><td>2023 Christmas Event</td><td style="text-align:right;">49/100</td><td style="text-align:right;">40/100</td></tr><tr><td>🚜 <strong>GD 410</strong></td><td>2024 &amp; 2025 Christmas Events</td><td style="text-align:right;">43/100</td><td style="text-align:right;">33/100</td></tr><tr><td>🚜 <strong>Vintage Tractor</strong></td><td>2025 Christmas Event</td><td style="text-align:right;">37/100</td><td style="text-align:right;">30/100</td></tr><tr><td>🚂 <strong>Train</strong></td><td>2025 Halloween Event</td><td style="text-align:right;">50/100</td><td style="text-align:right;">40/100</td></tr><tr><td>🚜 <strong>Medal Tractor</strong></td><td>Medal Promotion — unavailable</td><td style="text-align:right;">47/100</td><td style="text-align:right;">37/100</td></tr><tr><td>🚜 <strong>ROM2400</strong></td><td>Company Season 1</td><td style="text-align:right;">52/100</td><td style="text-align:right;">42/100</td></tr><tr><td>🚜 <strong>TX89</strong></td><td>Company Season 2</td><td style="text-align:right;">56/100</td><td style="text-align:right;">45/100</td></tr><tr><td>🚜 <strong>Falcon X</strong></td><td>Bonds Compensation — unobtainable</td><td style="text-align:right;">52/100</td><td style="text-align:right;">42/100</td></tr></tbody></table><h2 id="limited-exclusive-vehicles" tabindex="-1">Limited &amp; Exclusive Vehicles <a class="header-anchor" href="#limited-exclusive-vehicles" aria-label="Permalink to &quot;Limited &amp; Exclusive Vehicles&quot;">​</a></h2><p>Some vehicles cannot currently be purchased through the normal FarmCo shop.</p><p>These include vehicles obtained through:</p><ul><li>🎃 <strong>Halloween Events</strong></li><li>🎄 <strong>Christmas Events</strong></li><li>🏅 <strong>Promotions</strong></li><li>📦 <strong>Starter Packs</strong></li><li>🏢 <strong>Company Seasons</strong></li><li>🎁 <strong>Special Packs</strong></li><li>🛠️ <strong>Mod-exclusive content</strong></li><li>💰 <strong>Compensation rewards</strong></li></ul><p>Their availability may change if the developers bring an event or promotion back.</p><h2 id="using-tractors" tabindex="-1">Using Tractors <a class="header-anchor" href="#using-tractors" aria-label="Permalink to &quot;Using Tractors&quot;">​</a></h2><p>Tractors can be used with a variety of farming equipment. Depending on the equipment, a tractor can be used to:</p><ul><li>Plow fields</li><li>Cultivate fields</li><li>Plant crops</li><li>Tow trailers</li><li>Transport equipment</li><li>Perform forestry-related tasks</li><li>Complete farming tasks</li></ul><p>When purchasing a tractor, consider both its <strong>road speed</strong> and <strong>field speed</strong>, as well as the equipment you intend to use with it.</p><blockquote><p><strong>Tip:</strong> A tractor with a high road speed is useful for travelling around the map, while a high field speed can reduce the time spent working large fields.</p></blockquote><h1 id="waste-smells-very-bad" tabindex="-1">Waste smells very bad <a class="header-anchor" href="#waste-smells-very-bad" aria-label="Permalink to &quot;Waste smells very bad&quot;">​</a></h1>',45)])])}const p=e(d,[["render",l]]);export{m as __pageData,p as default};
